-- ============================================================================
-- Migration 910: electronics reference data (Phase 2)
-- ============================================================================
-- Generated by scripts/gen_910_electronics_reference_data.js -- do not hand-edit,
-- re-run the generator and diff instead.
--
-- One row per sourced engine input: key (which engine input), scope (which machine),
-- value, unit, where it came from. Global reference data, not organization data:
-- readable by every signed-in user, written only by migration.
--
-- status:
--   sourced                          a person confirmed the value applies to assembled boards
--   sourced_pending_confirmation     the value is real and sourced, but it describes a
--                                    bare-board fabrication machine and nobody has confirmed
--                                    it holds for assembly work. Engines must not price from
--                                    a pending row; they report a gap that names it.
--
-- 9 rows staged, from 3 machine files. Everything else the electronics
-- engines need (SMT placement rates, reflow speeds, solder and insertion times, harness cycle
-- times) is in no staged source and stays a written gap in the engine-input manifest.
-- Idempotent.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.electronics_reference_data (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  key text NOT NULL,
  scope text NOT NULL,
  value numeric NOT NULL CHECK (value > 0),
  unit text NOT NULL,
  status text NOT NULL CHECK (status IN ('sourced', 'sourced_pending_confirmation')),
  source text NOT NULL,
  source_ref text NOT NULL,
  note text,
  UNIQUE (key, scope)
);

ALTER TABLE public.electronics_reference_data ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS electronics_reference_data_read ON public.electronics_reference_data;
CREATE POLICY electronics_reference_data_read ON public.electronics_reference_data FOR SELECT
  TO authenticated USING (true);

